import math
def control(obs):
    h=math.radians(obs['hitch_deg'])
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    speed=-0.85
    if cam:
        axis=math.pi-h
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b)-axis
            s=d*math.cos(a); y=d*math.sin(a)
            if 1<s<14 and abs(y)>1.5:
                sides[0 if y>0 else 1].append((s,y))
        fits=[]
        for pts in sides:
            if len(pts)>=2:
                n=len(pts); sx=sum(p[0] for p in pts); sy=sum(p[1] for p in pts)
                den=sum(p[0]*p[0] for p in pts)-sx*sx/n
                m=(sum(p[0]*p[1] for p in pts)-sx*sy/n)/den if den>0.1 else 0
                fits.append((sy/n-m*sx/n,m))
        if len(fits)==2:
            c=(fits[0][0]+fits[1][0])/2
            m=(fits[0][1]+fits[1][1])/2
            y=c+10*m
            curvature=2*y/(100+y*y)
            desired=max(-0.75,min(0.75,-math.atan(10.2*curvature)))
        else:
            speed=-0.4
    else:
        speed=-0.4
    steer=math.degrees(math.atan(3.9*(math.sin(h)/10.2+0.38*(h-desired))))
    return (max(-42,min(42,steer)),speed,-41)

